class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        print("...")

class Dog(Animal):
    def __init__(self, name, breed):
        super().__init__(name)  # 부모 초기화!
        self.breed = breed

    def speak(self):
        print(f"{self.name}: 멍멍!")

dog = Dog("바둑이", "진돗개")
dog.speak()
print(dog.name, dog.breed)
